import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import {
    Package, CheckCircle, Clock, TrendingUp, DollarSign,
    AlertCircle, XCircle
} from 'lucide-react';
import orderService from '../../services/orderService';
import commissionService from '../../services/commissionService';
import {
    AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid,
    Tooltip, ResponsiveContainer, PieChart, Pie, Cell
} from 'recharts';

const COLORS = ['#4F46E5', '#10B981', '#F59E0B', '#EF4444'];

const Overview = () => {
    const { data: stats, isLoading: statsLoading } = useQuery({
        queryKey: ['sales-rep-stats'],
        queryFn: orderService.getSalesRepStats
    });

    const { data: earnings, isLoading: earningsLoading } = useQuery({
        queryKey: ['my-earnings'],
        queryFn: commissionService.getMyEarnings
    });

    const orderStatusData = [
        { name: 'Active', value: stats?.activeOrders || 0 },
        { name: 'Completed', value: stats?.completedOrders || 0 },
        { name: 'Cancelled', value: stats?.cancelledOrders || 0 },
        { name: 'Pending', value: (stats?.totalOrders || 0) - (stats?.activeOrders || 0) - (stats?.completedOrders || 0) - (stats?.cancelledOrders || 0) }
    ];

    return (
        <div className="space-y-6">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
                    Welcome back, Sales Rep!
                </h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Here's your performance overview
                </p>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard
                    icon={Package}
                    label="Total Orders"
                    value={stats?.totalOrders || 0}
                    color="indigo"
                    loading={statsLoading}
                />
                <StatCard
                    icon={CheckCircle}
                    label="Completed"
                    value={stats?.completedOrders || 0}
                    color="emerald"
                    subtitle={`${stats?.completionRate || 0}% completion rate`}
                    loading={statsLoading}
                />
                <StatCard
                    icon={DollarSign}
                    label="Total Revenue"
                    value={`$${(stats?.totalRevenue || 0).toLocaleString()}`}
                    color="teal"
                    loading={statsLoading}
                />
                <StatCard
                    icon={TrendingUp}
                    label="Total Earnings"
                    value={`$${(earnings?.summary?.totalEarnings || 0).toLocaleString()}`}
                    color="amber"
                    loading={earningsLoading}
                />
            </div>

            {/* Charts Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Order Status Distribution */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
                >
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                        Order Status Distribution
                    </h3>
                    <div className="flex items-center justify-center">
                        <ResponsiveContainer width="100%" height={300}>
                            <PieChart>
                                <Pie
                                    data={orderStatusData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={60}
                                    outerRadius={100}
                                    paddingAngle={5}
                                    dataKey="value"
                                >
                                    {orderStatusData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip />
                            </PieChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-center gap-4 mt-4">
                        {orderStatusData.map((item, index) => (
                            <div key={item.name} className="flex items-center gap-2">
                                <div
                                    className="w-3 h-3 rounded-full"
                                    style={{ backgroundColor: COLORS[index] }}
                                />
                                <span className="text-sm text-gray-600 dark:text-gray-400">
                                    {item.name} ({item.value})
                                </span>
                            </div>
                        ))}
                    </div>
                </motion.div>

                {/* Monthly Earnings */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
                >
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                        Monthly Earnings
                    </h3>
                    <ResponsiveContainer width="100%" height={300}>
                        <AreaChart data={earnings?.monthlyEarnings || []}>
                            <CartesianGrid strokeDasharray="3 3" />
                            <XAxis
                                dataKey="month"
                                tickFormatter={(date) => new Date(date).toLocaleString('default', { month: 'short' })}
                            />
                            <YAxis />
                            <Tooltip />
                            <Area
                                type="monotone"
                                dataKey="commission"
                                stackId="1"
                                stroke="#4F46E5"
                                fill="#4F46E5"
                                fillOpacity={0.3}
                                name="Commission"
                            />
                            <Area
                                type="monotone"
                                dataKey="salary"
                                stackId="1"
                                stroke="#10B981"
                                fill="#10B981"
                                fillOpacity={0.3}
                                name="Salary"
                            />
                        </AreaChart>
                    </ResponsiveContainer>
                </motion.div>
            </div>

            {/* Top Products by Earnings */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
            >
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                    Top Products by Commission
                </h3>

                {earnings?.topProducts?.length === 0 ? (
                    <p className="text-center text-gray-500 py-8">No earnings data yet</p>
                ) : (
                    <div className="space-y-4">
                        {earnings?.topProducts?.map((product, index) => (
                            <div
                                key={product.productId}
                                className="flex items-center gap-4 p-3 bg-gray-50 dark:bg-gray-900 rounded-lg"
                            >
                                <div className="flex items-center justify-center w-8 h-8 rounded-full bg-indigo-100 dark:bg-indigo-900/30 text-indigo-600 font-bold text-sm">
                                    #{index + 1}
                                </div>

                                <div className="h-12 w-12 rounded-lg bg-gray-200 dark:bg-gray-700 overflow-hidden flex-shrink-0">
                                    {product.productImage ? (
                                        <img src={product.productImage} alt={product.productName} className="h-full w-full object-cover" />
                                    ) : (
                                        <Package className="h-full w-full p-2 text-gray-400" />
                                    )}
                                </div>

                                <div className="flex-1">
                                    <p className="font-medium text-gray-900 dark:text-white">
                                        {product.productName}
                                    </p>
                                    <p className="text-sm text-gray-500">
                                        {product.orderCount} orders
                                    </p>
                                </div>

                                <div className="text-right">
                                    <p className="font-bold text-gray-900 dark:text-white">
                                        ${product.totalEarnings.toLocaleString()}
                                    </p>
                                    <p className="text-xs text-gray-500">total commission</p>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </motion.div>
        </div>
    );
};

const StatCard = ({ icon: Icon, label, value, color, subtitle, loading }) => {
    const colorVariants = {
        indigo: 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400',
        emerald: 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400',
        teal: 'bg-teal-100 text-teal-600 dark:bg-teal-900/30 dark:text-teal-400',
        amber: 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400',
    };

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
        >
            {loading ? (
                <div className="animate-pulse space-y-3">
                    <div className="h-12 w-12 bg-gray-200 dark:bg-gray-700 rounded-lg" />
                    <div className="h-4 w-24 bg-gray-200 dark:bg-gray-700 rounded" />
                    <div className="h-8 w-32 bg-gray-200 dark:bg-gray-700 rounded" />
                </div>
            ) : (
                <>
                    <div className="flex items-center gap-4">
                        <div className={`p-3 rounded-lg ${colorVariants[color]}`}>
                            <Icon className="h-6 w-6" />
                        </div>
                        <div>
                            <p className="text-sm text-gray-500 dark:text-gray-400">{label}</p>
                            <p className="text-2xl font-bold text-gray-900 dark:text-white">{value}</p>
                        </div>
                    </div>
                    {subtitle && (
                        <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">{subtitle}</p>
                    )}
                </>
            )}
        </motion.div>
    );
};

export default Overview;
